SEMAPHORES = {1:[1,2,4,3], 2:[1,2,4,3], 3:[1,2,4,3], 4:[1,2,4,3],
              5:[5,7,8,6], 6:[5,7,8,6], 7:[5,7,8,6], 8:[5,7,8,6]}

def find_contig_groups(row):
    groups = []
    start = None
    for c, val in enumerate(row):
        if val != 0:
            if start is None:
                start = c
        else:
            if start is not None:
                groups.append((start, c-1, [row[i] for i in range(start, c)]))
                start = None
    if start is not None:
        groups.append((start, len(row)-1, [row[i] for i in range(start, len(row))]))
    return groups

def find_exact_semigroups(row):
    found_positions = set()
    result = {}

    groups = find_contig_groups(row)
    for start, end, vals in groups:
        if len(vals) >= 2:
            for val, seq in SEMAPHORES.items():
                if vals == seq:
                    result[(start, end)] = seq
                    found_positions.update(range(start, end+1))

    return found_positions, result

def transform_row_v4(row):
    cols = len(row)
    result = [0] * cols

    preserved_positions, semigroups = find_exact_semigroups(row)

    # Check if entire non-zero content is preserved
    all_preserved = True
    for c, val in enumerate(row):
        if val != 0 and c not in preserved_positions:
            all_preserved = False
            break

    if all_preserved:
        return list(row)

    groups = find_contig_groups(row)

    has_multigroup = any(len(g[2]) >= 2 for g in groups)

    if has_multigroup:
        new_vals = []
        prev_end = -1
        for start, end, vals in groups:
            if len(vals) >= 2:
                if (start, end) not in semigroups:
                    pass  # Clear this group
                else:
                    for i in range(prev_end + 1, end + 1):
                        new_vals.append(row[i])
            prev_end = end

        for start, end, vals in groups:
            if len(vals) < 2:
                for i in range(prev_end + 1, end + 1):
                    new_vals.append(row[i])

        while len(new_vals) < cols:
            new_vals.append(0)
        result = new_vals[:cols]
        return result

    for start, end, vals in groups:
        for val in vals:
            seq = SEMAPHORES.get(val)
            if seq is None:
                continue

            seq_idx = seq.index(val)
            start_col = start - seq_idx

            for j, s_val in enumerate(seq):
                out_col = start_col + j
                if 0 <= out_col < cols:
                    result[out_col] = s_val

    return result

